+const base64UrlEncode = (buffer: Buffer): string => {
+  return buffer
+    .toString("base64")
+    .replace(/\+/g, "-")
+    .replace(/\//g, "_")
+    .replace(/=/g, "");
+};
+
+const base64UrlDecode = (str: string): Buffer => {
+  str += "=".repeat((4 - (str.length % 4)) % 4);
+  return Buffer.from(str.replace(/-/g, "+").replace(/_/g, "/"), "base64");
+};
+
+export const createSessionToken = (session: Session): string => {
+  const now = Math.floor(Date.now() / 1000);
+  const payload: SessionToken = {
+    id: session.id,
+    userId: session.userId,
+    iat: now,
+    exp: now + TOKEN_LIFETIME,
+  };
+
+  const header = base64UrlEncode(Buffer.from(JSON.stringify({ alg: "HS256", typ: "JWT" })));
+  const encodedPayload = base64UrlEncode(Buffer.from(JSON.stringify(payload)));
+
+  const signature = crypto
+    .createHmac("sha256", SECRET_KEY)
+    .update(`${header}.${encodedPayload}`)
+    .digest();
+  const encodedSignature = base64UrlEncode(signature);
+
+  return `${header}.${encodedPayload}.${encodedSignature}`;
+};
+
+export const verifySessionToken = (token: string): Session | null => {
+  try {
+    const parts = token.split(".");
+    if (parts.length !== 3) return null;
+
+    const [header, payload, signature] = parts;
+
+    const expectedSignature = crypto
+      .createHmac("sha256", SECRET_KEY)
+      .update(`${header}.${payload}`)
+      .digest();
+    const expectedSignatureB64 = base64UrlEncode(expectedSignature);
+
+    if (signature !== expectedSignatureB64) return null;
+
+    const decodedPayload = JSON.parse(base64UrlDecode(payload).toString("utf-8")) as SessionToken;
+
+    const now = Math.floor(Date.now() / 1000);
+    if (decodedPayload.exp <= now) return null;
+
+    return {
+      id: decodedPayload.id,
+      userId: decodedPayload.userId,
+      revokedAt: null,
+    };
+  } catch {
+    return null;
+  }
+};
+
 export const revokeSession = async (id: string): Promise<void> => {
   await pool.query("UPDATE sessions SET revoked_at = now() WHERE id = $1", [id]);
 };
